 Chapter 4 Read-level simulations Read-level simulations were performed by introducing synthetic SNVs directly into the original RNA-seq BAM files to evaluate variant calling performance across different variant allele frequencies (VAFs) and sequencing depths. Candidate sites were sampled from predefined genomic regions after excluding previously identified variants and their ±100 bp flanking regions. Eligible reads or fragments were selected based on alignment status and sequencing quality, and reference-supporting bases were modified according to the target VAF. Modified BAM files and corresponding ground-truth records were generated for downstream evaluation. For VAF simulations, five target VAFs (0.05, 0.10, 0.25, 0.50, and 0.75) were evaluated at sequencing depths ≥40×, with 10,000 candidate sites for 10x Genomics and 3,000 for Smart-seq2. For depth simulations, a fixed VAF of 0.4 was used. The Smart-seq2 workflow sampled 50,000 candidate sites and selected up to 3,000 sites per effective-depth bin (5–9×, 10–24×, 25–49×, and ≥50×). As the simulation procedures were similar across the two sequencing platforms, only the 10x Genomics VAF simulation and Smart-seq2 depth simulation are presented below as representative workflows to avoid redundancy. 4.1 10x VAF simulation simulation-region preparation Step 1. Extract and merge protein-coding exon regions from the GTF annotation. gtf=&quot;/home/tantingting/scmut/ref/refdata-gex-GRCh38-2024-A/genes/genes.gtf&quot; outdir=&quot;/mnt/storage/tantingting/scmut/simu/region&quot; mkdir -p &quot;$outdir&quot; cat &quot;$gtf&quot; | awk &#39;BEGIN{OFS=&quot;	&quot;} $3==&quot;exon&quot; &amp;&amp; $0 ~ /gene_type &quot;protein_coding&quot;/ &amp;&amp; $1 ~ /^chr([1-9]|1[0-9]|2[0-2])$/ { print $1,$4-1,$5 }&#39; | bedtools sort -i - | bedtools merge -i - &gt; &quot;${outdir}/protein_coding_exon.merged.bed&quot; wc -l &quot;${outdir}/protein_coding_exon.merged.bed&quot; awk &#39;{sum+=$3-$2} END{print &quot;Total exon length:&quot;,sum/1000000,&quot;Mb&quot;}&#39; &quot;${outdir}/protein_coding_exon.merged.bed&quot; head &quot;${outdir}/protein_coding_exon.merged.bed&quot; Step 2. Intersect protein-coding exon regions with scRNA-seq regions covered at ≥10× for each sample. samples=(Acral1 Acral2 Acral3pre Acral3post Acral4 Cutaneous1 Cutaneous1Lym Cutaneous2) for sample in &quot;${samples[@]}&quot; do INBED=&quot;/mnt/storage/tantingting/scmut/WES_gold/2_melanoma/region/whole/scRNA_${sample}_gt10_strict.bed&quot; OUTBED=&quot;${OUTDIR}/${sample}.exon_gt10.bed&quot; bedtools intersect -a $EXON_BED -b $INBED | bedtools sort -i - | bedtools merge -i - &gt; $OUTBED n=$(wc -l &lt; $OUTBED) mb=$(awk &#39; {sum+=$3-$2} END{printf &quot;%.2f&quot;,sum/1000000} &#39; $OUTBED) echo -e &quot;melanoma	${sample}	${n}	${mb}&quot; &gt;&gt; ${OUTDIR}/summary.tsv done Step 3. Exclude sites identified by the union of six variant callers and their ±100 bp flanking regions to obtain the final simulation regions. REGION_DIR=&quot;/mnt/storage/tantingting/scmut/simu/region/exon_gt10&quot; UNION_DIR=&quot;/mnt/storage/tantingting/scmut/simu/original_union_sites&quot; OUT_DIR=&quot;/mnt/storage/tantingting/scmut/simu/region/final_sim_region&quot; mkdir -p &quot;$OUT_DIR&quot; echo -e &quot;Sample	N_region	Length_Mb&quot; &gt; &quot;${OUT_DIR}/final_region_summary.tsv&quot; for sample in P4_cSCC P5_cSCC P6_cSCC P7_cSCC P9_cSCC P10_cSCC Acral1 Acral2 Acral3pre Acral3post Acral4 Cutaneous1 Cutaneous1Lym Cutaneous2 do bedtools subtract -a &quot;${REGION_DIR}/${sample}.exon_gt10.bed&quot; \ -b &quot;${UNION_DIR}/${sample}.union_6tools.plusminus100bp.bed&quot; | bedtools sort -i - | bedtools merge -i - \ &gt; &quot;${OUT_DIR}/${sample}.final_sim_region.bed&quot; n=$(wc -l &lt; &quot;${OUT_DIR}/${sample}.final_sim_region.bed&quot;) mb=$(awk &#39;{sum+=$3-$2} END{printf &quot;%.2f&quot;,sum/1000000}&#39; &quot;${OUT_DIR}/${sample}.final_sim_region.bed&quot;) echo -e &quot;${sample}	${n}	${mb}&quot; &gt;&gt; &quot;${OUT_DIR}/final_region_summary.tsv&quot; done column -t &quot;${OUT_DIR}/final_region_summary.tsv&quot; VAF simulation code REF=/home/tantingting/scmut/ref/bwa_ref/genome.fa REGION_DIR=/mnt/storage/tantingting/scmut/simu/region/final_sim_region_dp40 OUTDIR=/mnt/storage/tantingting/scmut/simu/direct_spike_vaf_dp40_final N_SITE=10000 FLANK=0 MINDEPTH=40 MINMUTREADS=2 THREADS=16 SEED=1234 VAFS=(0.05 0.1 0.25 0.5 0.75) mkdir -p ${OUTDIR}/{scripts,sites,window,bam,log,truth,summary} mkdir -p ${OUTDIR}/cache #samples=(P4_cSCC) #samples=( #P4_cSCC P5_cSCC P6_cSCC P7_cSCC P9_cSCC P10_cSCC #Acral1 Acral2 Acral3pre Acral3post Acral4 Cutaneous1 Cutaneous1Lym Cutaneous2 #) samples=(&quot;$@&quot;) if [[ ${#samples[@]} -eq 0 ]]; then echo &quot;[ERROR] No sample specified&quot; exit 1 fi get_bam() { sample=$1 case &quot;$sample&quot; in P*_cSCC) echo &quot;/mnt/storage/tantingting/scmut/bam/1_cSCC_scRNA/${sample}/outs/${sample}_map.bam&quot; ;; Acral1) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Acral1_SRR20791206/outs/Acral1_SRR20791206_map.bam&quot; ;; Acral2) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Acral2_SRR20791205/outs/Acral2_SRR20791205_map.bam&quot; ;; Acral3pre) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Acral3pre_SRR20791203/outs/Acral3pre_SRR20791203_map.bam&quot; ;; Acral3post) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Acral3post_SRR20791202/outs/Acral3post_SRR20791202_map.bam&quot; ;; Acral4) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Acral4_SRR20791201/outs/Acral4_SRR20791201_map.bam&quot; ;; Cutaneous1) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Cutaneous1_SRR20791198/outs/Cutaneous1_SRR20791198_map.bam&quot; ;; Cutaneous1Lym) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Cutaneous1Lym_SRR20791196/outs/Cutaneous1Lym_SRR20791196_map.bam&quot; ;; Cutaneous2) echo &quot;/mnt/storage/tantingting/scmut/bam/2_melanoma_scRNA/Cutaneous2_SRR20791197/outs/Cutaneous2_SRR20791197_map.bam&quot; ;; *) echo &quot;NA&quot; ;; esac } ############################################ # 1. Generate fixed master sites for each sample ############################################ cat &gt; ${OUTDIR}/scripts/make_master_sites.py &lt;&lt; &#39;PY&#39; import sys, random, subprocess, bisect import os import pickle region_bed, ref, n_site, out, seed = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4], int(sys.argv[5]) random.seed(seed) bases = [&quot;A&quot;, &quot;C&quot;, &quot;G&quot;, &quot;T&quot;] regions, cum = [], [] total = 0 with open(region_bed) as f: for line in f: if not line.strip() or line.startswith(&quot;#&quot;): continue chrom, start, end = line.strip().split()[:3] start, end = int(start), int(end) if end &lt;= start: continue total += end - start regions.append((chrom, start, end)) cum.append(total) if total == 0: sys.exit(&quot;No valid regions&quot;) seen, tries, max_tries = set(), 0, n_site * 200 with open(out, &quot;w&quot;) as w: while len(seen) &lt; n_site and tries &lt; max_tries: tries += 1 i = bisect.bisect_left(cum, random.randint(1, total)) chrom, start, end = regions[i] pos = random.randint(start, end - 1) + 1 key = (chrom, pos) if key in seen: continue try: fa = subprocess.check_output([&quot;samtools&quot;, &quot;faidx&quot;, ref, f&quot;{chrom}:{pos}-{pos}&quot;], text=True).splitlines() ref_base = &quot;&quot;.join(fa[1:]).upper() except Exception: continue if len(ref_base) != 1 or ref_base not in bases: continue alt = random.choice([b for b in bases if b != ref_base]) seen.add(key) w.write(f&quot;{chrom}	{pos}	{pos}	{ref_base}	{alt}
&quot;) PY ############################################ # 2. Direct spike-in script # Key modifications: Instead of randomly modifying individual reads, fragments are first selected based on query_name. During the second BAM pass, both R1 and R2 sharing the same query_name are modified if they cover the target site. ############################################ cat &gt; ${OUTDIR}/scripts/direct_spike_bam.py &lt;&lt; &#39;PY&#39; import sys, random, pysam, math import bisect from collections import defaultdict import os import pickle from collections import defaultdict bam_in, sites_file, ref_fa, bam_out, truth_out, min_depth, min_mutreads, seed, cache_file = sys.argv[1:10] min_depth, min_mutreads, seed = int(min_depth), int(min_mutreads), int(seed) random.seed(seed) bam = pysam.AlignmentFile(bam_in, &quot;rb&quot;) sites = [] with open(sites_file) as f: for line in f: if not line.strip() or line.startswith(&quot;#&quot;): continue fs = line.strip().split() chrom, pos, end, vaf, ref_base, alt = fs[0], int(fs[1]), int(fs[2]), float(fs[3]), fs[4].upper(), fs[5].upper() sites.append((chrom, pos, vaf, ref_base, alt)) sites.sort(key=lambda x: (x[0], x[1])) # fragment_edit_map: # key = (chrom, pos, query_name) # value = alt fragment_edit_map = {} truth = [] ############################################ # Optimization 1: Group sites by chromosome # Optimization 2: Compute aligned_pairs only once per read # Optimization 3: Collect candidate fragments for each site ############################################ if os.path.exists(cache_file): print( f&quot;[INFO] load cache: {cache_file}&quot;, file=sys.stderr ) with open(cache_file, &quot;rb&quot;) as f: site_info = pickle.load(f) for chrom, pos, vaf, ref_base, alt in sites: if (chrom, pos) not in site_info: continue site_info[(chrom, pos)][&quot;vaf&quot;] = vaf else: print( f&quot;[INFO] build cache: {cache_file}&quot;, file=sys.stderr ) site_info = {} # Build the site information table for chrom, pos, vaf, ref_base, alt in sites: site_info[(chrom, pos)] = { &quot;vaf&quot;: vaf, &quot;ref&quot;: ref_base, &quot;alt&quot;: alt, &quot;cover&quot;: 0, &quot;candidates&quot;: set() } chr_sites = defaultdict(set) for chrom, pos, vaf, ref_base, alt in sites: chr_sites[chrom].add(pos) print( f&quot;[INFO] {len(site_info)} sites loaded&quot;, file=sys.stderr ) ############################################ # Batch scan by chromosome ############################################ for chrom in sorted(chr_sites.keys()): target_pos = sorted(chr_sites[chrom]) # pysam.fetch() uses 0-based, half-open intervals [start, end) start = min(target_pos) - 1 end = max(target_pos)+1 print( f&quot;[INFO] scanning {chrom}&quot;, file=sys.stderr ) try: iterator = bam.fetch(chrom, start, end) except ValueError: continue n_read = 0 for r in iterator: if r.is_unmapped: continue if r.is_secondary: continue if r.is_supplementary: continue seq = r.query_sequence if seq is None: continue n_read += 1 aligned = { rp + 1: qp for qp, rp in r.get_aligned_pairs(matches_only=False) if qp is not None and rp is not None } if not aligned: continue #read_start = min(aligned) #read_end = max(aligned) #1-based genomic position read_start = r.reference_start + 1 read_end = r.reference_end if read_end is None: continue #################################### # Find target sites covered by the current read #################################### left = bisect.bisect_left( target_pos, read_start ) right = bisect.bisect_right( target_pos, read_end ) covered_sites = target_pos[left:right] if not covered_sites: continue for pos in covered_sites: qp = aligned.get(pos) if qp is None: continue base = seq[qp].upper() if base not in &quot;ACGT&quot;: continue info = site_info[(chrom, pos)] info[&quot;cover&quot;] += 1 if base == info[&quot;ref&quot;]: info[&quot;candidates&quot;].add( r.query_name ) print( f&quot;[INFO] {chrom}: {n_read} reads scanned&quot;, file=sys.stderr ) ################################################## # Save the cache after the first scan ################################################## with open(cache_file, &quot;wb&quot;) as f: pickle.dump(site_info, f) print( f&quot;[INFO] cache saved: {cache_file}&quot;, file=sys.stderr ) ############################################ # Select fragments to modify based on coverage depth and VAF ############################################ fragment_edit_map = {} truth = [] for (chrom, pos), info in site_info.items(): dp = info[&quot;cover&quot;] if dp &lt; min_depth: continue candidates = list( info[&quot;candidates&quot;] ) if len(candidates) == 0: continue target_alt_reads = max( min_mutreads, math.ceil(dp * info[&quot;vaf&quot;]) ) n_choose = min( len(candidates), target_alt_reads ) chosen_names = random.sample( candidates, n_choose ) for name in chosen_names: fragment_edit_map[ (chrom, pos, name) ] = info[&quot;alt&quot;] truth.append( ( chrom, pos, info[&quot;ref&quot;], info[&quot;alt&quot;], dp, len(candidates), n_choose, &quot;NA&quot; ) ) print( f&quot;[INFO] fragment_edit_map={len(fragment_edit_map)}&quot;, file=sys.stderr ) ############################################ # Second pass: Reopen the BAM and write reads sequentially # # First, check query_name to identify reads requiring modification. # Compute aligned_pairs only for selected fragments. # This allows most unmodified reads to be written directly. ############################################ bam.close() bam = pysam.AlignmentFile(bam_in, &quot;rb&quot;) out = pysam.AlignmentFile(bam_out, &quot;wb&quot;, template=bam) edited_reads = 0 edited_bases = 0 site_edited_bases = defaultdict(int) edit_by_qname = defaultdict(lambda: defaultdict(dict)) for chrom, pos, qname in fragment_edit_map: alt = fragment_edit_map[(chrom, pos, qname)] edit_by_qname[qname][chrom][pos] = alt print( f&quot;[INFO] edit_by_qname={len(edit_by_qname)}&quot;, file=sys.stderr ) for r in bam: if r.is_unmapped or r.is_secondary or r.is_supplementary or r.query_sequence is None: out.write(r) continue qname = r.query_name if qname not in edit_by_qname: out.write(r) continue chrom = r.reference_name if chrom is None: out.write(r) continue if chrom not in edit_by_qname[qname]: out.write(r) continue target_edits = edit_by_qname[qname][chrom] seq = list(r.query_sequence) quals = r.query_qualities changed = 0 ######################################## # Compute aligned_pairs only for reads that may require modification ######################################## for qp, rp in r.get_aligned_pairs(matches_only=False): if qp is None or rp is None: continue pos = rp + 1 if pos not in target_edits: continue alt = target_edits[pos] if qp &lt; len(seq) and seq[qp].upper() in &quot;ACGT&quot; and seq[qp].upper() != alt: seq[qp] = alt changed += 1 site_edited_bases[(chrom, pos)] += 1 if changed &gt; 0: r.query_sequence = &quot;&quot;.join(seq) r.query_qualities = quals edited_reads += 1 edited_bases += changed out.write(r) out.close() bam.close() ############################################ # Output ground truth # mut_reads_planned = Number of selected query_names # mut_bases_edited = Number of read bases actually modified # real_vaf = mut_bases_edited / dp ############################################ with open(truth_out, &quot;w&quot;) as w: w.write(&quot;chrom	pos	ref	alt	dp	candidate_fragments	mut_fragments_planned	mut_bases_edited	real_vaf
&quot;) for chrom, pos, ref_base, alt, dp, n_candidate, n_choose, _ in truth: mut_bases = site_edited_bases.get((chrom, pos), 0) real_vaf = mut_bases / dp if dp &gt; 0 else 0 w.write(&quot;	&quot;.join(map(str, [chrom, pos, ref_base, alt, dp, n_candidate, n_choose, mut_bases, real_vaf])) + &quot;
&quot;) sys.stderr.write(f&quot;[INFO] sites_input={len(sites)} truth_sites={len(truth)} edited_reads={edited_reads} edited_bases={edited_bases}
&quot;) PY manifest=${OUTDIR}/summary/prepare_manifest.tsv if [[ ! -s ${manifest} ]]; then echo -e &quot;Sample	Mode	VAF	MasterSites	Sites	WindowBed	OriginalSubsetBam	SpikeinBam	CalmdBam	Truth&quot; &gt; ${manifest} fi ############################################ # 3. Main loop ############################################ for sample in &quot;${samples[@]}&quot;; do echo &quot;========== ${sample} ==========&quot; bam=$(get_bam ${sample}) region_bed=${REGION_DIR}/${sample}.final_sim_region_dp40.bed master_sites=${OUTDIR}/sites/${sample}.master_sites.txt sample_window=${OUTDIR}/window/${sample}.master.window.bed sample_subset=${OUTDIR}/bam/${sample}.master.original_subset.bam [[ &quot;${bam}&quot; != &quot;NA&quot; ]] || { echo &quot;[SKIP] unknown sample: ${sample}&quot;; continue; } [[ -f ${region_bed} ]] || { echo &quot;[SKIP] no region: ${region_bed}&quot;; continue; } [[ -f ${bam} ]] || { echo &quot;[SKIP] no bam: ${bam}&quot;; continue; } [[ -f ${bam}.bai ]] || samtools index ${bam} if [[ -s ${master_sites} ]]; then echo &quot;[1] master sites exists, skip: ${master_sites}&quot; else echo &quot;[1] make master sites&quot; python ${OUTDIR}/scripts/make_master_sites.py ${region_bed} ${REF} ${N_SITE} ${master_sites} ${SEED} fi n_master=$(wc -l &lt; ${master_sites}) echo &quot;[INFO] master sites: ${n_master}&quot; [[ ${n_master} -gt 0 ]] || { echo &quot;[SKIP] no master sites: ${sample}&quot;; continue; } if [[ -s ${sample_window} ]]; then echo &quot;[2] master window exists, skip: ${sample_window}&quot; else echo &quot;[2] make master window&quot; awk -v OFS=&quot;	&quot; -v flank=${FLANK} &#39;{s=$2-1-flank; e=$3+flank; if(s&lt;0)s=0; print $1,s,e}&#39; ${master_sites} \ | sort -k1,1 -k2,2n | bedtools merge &gt; ${sample_window} fi if [[ -s ${sample_subset} &amp;&amp; -s ${sample_subset}.bai ]]; then echo &quot;[3] master subset BAM exists, skip: ${sample_subset}&quot; else echo &quot;[3] subset BAM once&quot; samtools view -@ ${THREADS} -P -b -L ${sample_window} ${bam} &gt; ${sample_subset} samtools index ${sample_subset} fi for vaf in &quot;${VAFS[@]}&quot;; do tag=${sample}.vaf${vaf} cache=${OUTDIR}/cache/${sample}.site_info.pkl sites=${OUTDIR}/sites/${tag}.sites.txt spikein=${OUTDIR}/bam/${tag}.spikein.bam spikein_sorted=${OUTDIR}/bam/${tag}.spikein.sorted.bam spikein_calmd=${OUTDIR}/bam/${tag}.spikein.sorted.calmd.bam truth=${OUTDIR}/truth/${tag}.truth.tsv echo &quot;[4] ${sample} VAF=${vaf}&quot; if [[ -s ${sites} ]]; then echo &quot;[4] sites exists, skip: ${sites}&quot; else awk -v OFS=&quot;	&quot; -v vaf=${vaf} &#39;{print $1,$2,$3,vaf,$4,$5}&#39; ${master_sites} &gt; ${sites} fi if [[ -s ${spikein_calmd} &amp;&amp; -s ${spikein_calmd}.bai &amp;&amp; -s ${truth} ]]; then echo &quot;[5] calmd spike-in BAM exists, skip: ${spikein_calmd}&quot; else echo &quot;[5] direct spike-in BAM&quot; python ${OUTDIR}/scripts/direct_spike_bam.py ${sample_subset} ${sites} ${REF} ${spikein} \ ${truth} ${MINDEPTH} ${MINMUTREADS} ${SEED} ${cache} &gt; ${OUTDIR}/log/${tag}.log 2&gt;&amp;1 [[ -s ${spikein} ]] || { echo &quot;[ERROR] direct spike-in failed: check ${OUTDIR}/log/${tag}.log&quot;; continue; } echo &quot;[6] sort/index&quot; samtools sort -@ ${THREADS} -o ${spikein_sorted} ${spikein} samtools index ${spikein_sorted} samtools quickcheck ${spikein_sorted} echo &quot;[7] calmd/index&quot; samtools calmd -@ ${THREADS} -b ${spikein_sorted} ${REF} &gt; ${spikein_calmd} samtools index ${spikein_calmd} samtools quickcheck ${spikein_calmd} fi n_truth=$(($(wc -l &lt; ${truth}) - 1)) echo &quot;[INFO] truth sites: ${n_truth}&quot; if ! awk -v s=&quot;${sample}&quot; -v v=&quot;${vaf}&quot; &#39;$1==s &amp;&amp; $2==&quot;VAF&quot; &amp;&amp; $3==v{found=1} END{exit found?0:1}&#39; ${manifest}; then echo -e &quot;${sample}	VAF	${vaf}	${master_sites}	${sites}	${sample_window}	${sample_subset}	${spikein_sorted}	${spikein_calmd}	${truth}&quot; &gt;&gt; ${manifest} fi done echo &quot;[DONE] ${sample}&quot; done VAF simulation plotting suppressPackageStartupMessages({ library(data.table) library(dplyr) library(ggplot2) library(stringr) library(R.utils) }) base_dir &lt;- &quot;/mnt/storage/tantingting/scmut/simu/direct_spike_vaf_dp40_final&quot; truth_dir &lt;- file.path(base_dir, &quot;truth&quot;) vcf_dir &lt;- file.path(base_dir, &quot;caller/newonly&quot;) out_dir &lt;- file.path(base_dir, &quot;performance_plot&quot;) dir.create(out_dir, recursive = TRUE, showWarnings = FALSE) tools &lt;- c(&quot;Freebayes&quot;, &quot;GATK&quot;, &quot;Monopogen&quot;, &quot;Strelka2&quot;, &quot;VarScan2&quot;) vafs &lt;- c(&quot;0.05&quot;, &quot;0.1&quot;, &quot;0.25&quot;, &quot;0.5&quot;, &quot;0.75&quot;) truth_files &lt;- list.files(truth_dir, pattern = &quot;\.truth\.tsv$&quot;, full.names = FALSE) samples &lt;- sort(unique(sub(&quot;\.vaf.*$&quot;, &quot;&quot;, truth_files))) read_truth &lt;- function(f) { x &lt;- fread(f) names(x) &lt;- str_replace_all(names(x), &quot;^#&quot;, &quot;&quot;) x[, chrom := as.character(chrom)] x[, pos := as.integer(pos)] x[, ref := toupper(as.character(ref))] x[, alt := toupper(as.character(alt))] unique(x[, .(chrom, pos, ref, alt)]) } read_vcf &lt;- function(f) { if (!file.exists(f)) return(data.table(chrom = character(), pos = integer(), ref = character(), alt = character())) x &lt;- tryCatch(fread(cmd = paste(&quot;bcftools query -f &#39;%CHROM\t%POS\t%REF\t%ALT\n&#39;&quot;, shQuote(f))), error = function(e) data.table()) if (nrow(x) == 0) return(data.table(chrom = character(), pos = integer(), ref = character(), alt = character())) setnames(x, c(&quot;chrom&quot;, &quot;pos&quot;, &quot;ref&quot;, &quot;alt&quot;)) x[, chrom := as.character(chrom)] x[, pos := as.integer(pos)] x[, ref := toupper(as.character(ref))] x[, alt := toupper(as.character(alt))] x &lt;- x[nchar(ref) == 1 &amp; nchar(alt) == 1] unique(x[, .(chrom, pos, ref, alt)]) } res &lt;- list() k &lt;- 1 for (sample in samples) { for (vaf in vafs) { truth_file &lt;- file.path(truth_dir, paste0(sample, &quot;.vaf&quot;, vaf, &quot;.truth.tsv&quot;)) if (!file.exists(truth_file)) next truth &lt;- read_truth(truth_file) truth_key &lt;- paste(truth$chrom, truth$pos, truth$ref, truth$alt, sep = &quot;:&quot;) for (tool in tools) { vcf_file &lt;- file.path(vcf_dir, paste0(sample, &quot;.vaf&quot;, vaf, &quot;.&quot;, tool, &quot;.newonly.vcf.gz&quot;)) call &lt;- read_vcf(vcf_file) call_key &lt;- paste(call$chrom, call$pos, call$ref, call$alt, sep = &quot;:&quot;) tp &lt;- sum(call_key %in% truth_key) fp &lt;- sum(!call_key %in% truth_key) fn &lt;- sum(!truth_key %in% call_key) precision &lt;- ifelse(tp + fp &gt; 0, tp/(tp + fp), NA_real_) recall &lt;- ifelse(tp + fn &gt; 0, tp/(tp + fn), NA_real_) f1 &lt;- ifelse(!is.na(precision + recall) &amp; precision + recall &gt; 0, 2 * precision * recall/(precision + recall), NA_real_) res[[k]] &lt;- data.table(sample = sample, vaf = as.numeric(vaf), tool = tool, truth_n = length(truth_key), call_n = length(call_key), TP = tp, FP = fp, FN = fn, Precision = precision, Recall = recall, F1 = f1) k &lt;- k + 1 } } } perf &lt;- rbindlist(res) perf[, tool := factor(tool, levels = tools)] perf[, vaf_label := factor(vaf, levels = as.numeric(vafs), labels = vafs)] fwrite(perf, file.path(out_dir, &quot;vaf_performance_summary.tsv&quot;), sep = &quot;	&quot;) tool_cols &lt;- c(Freebayes = &quot;#1F78B4&quot;, GATK = &quot;#33A02C&quot;, Monopogen = &quot;#6A3D9A&quot;, Strelka2 = &quot;#B15928&quot;, VarScan2 = &quot;#E31A1C&quot;) plot_metric &lt;- function(metric) { p &lt;- ggplot(perf, aes(x = vaf_label, y = .data[[metric]], fill = tool, color = tool)) + geom_boxplot(outlier.shape = NA, width = 0.65, position = position_dodge(width = 0.8), alpha = 0.65) + geom_point(position = position_jitterdodge(jitter.width = 0.12, dodge.width = 0.8), size = 1.4, alpha = 0.75) + scale_fill_manual(values = tool_cols) + scale_color_manual(values = tool_cols) + scale_y_continuous(limits = c(0, 1), breaks = seq(0, 1, 0.25)) + labs(x = &quot;Simulated VAF&quot;, y = metric, fill = NULL, color = NULL) + theme_classic(base_size = 14) + theme(axis.text.x = element_text(size = 12, color = &quot;black&quot;), axis.text.y = element_text(size = 12, color = &quot;black&quot;), axis.title = element_text(size = 15, color = &quot;black&quot;, face = &quot;bold&quot;), legend.position = &quot;top&quot;, legend.text = element_text(size = 11), panel.grid.major.y = element_line(color = &quot;grey90&quot;, linewidth = 0.3)) ggsave(file.path(out_dir, paste0(&quot;VAF_&quot;, metric, &quot;_boxplot.pdf&quot;)), p, width = 7.5, height = 4.8) ggsave(file.path(out_dir, paste0(&quot;VAF_&quot;, metric, &quot;_boxplot.png&quot;)), p, width = 7.5, height = 4.8, dpi = 300) } plot_metric(&quot;Recall&quot;) plot_metric(&quot;Precision&quot;) plot_metric(&quot;F1&quot;) perf_long &lt;- melt(perf, id.vars = c(&quot;sample&quot;, &quot;vaf&quot;, &quot;vaf_label&quot;, &quot;tool&quot;, &quot;truth_n&quot;, &quot;call_n&quot;, &quot;TP&quot;, &quot;FP&quot;, &quot;FN&quot;), measure.vars = c(&quot;Recall&quot;, &quot;Precision&quot;, &quot;F1&quot;), variable.name = &quot;Metric&quot;, value.name = &quot;Score&quot;) p_all &lt;- ggplot(perf_long, aes(x = vaf_label, y = Score, fill = tool, color = tool)) + geom_boxplot(outlier.shape = NA, width = 0.65, position = position_dodge(width = 0.8), alpha = 0.65) + geom_point(position = position_jitterdodge(jitter.width = 0.12, dodge.width = 0.8), size = 1.1, alpha = 0.7) + facet_wrap(~Metric, nrow = 1) + scale_fill_manual(values = tool_cols) + scale_color_manual(values = tool_cols) + scale_y_continuous(limits = c(0, 1), breaks = seq(0, 1, 0.25)) + labs(x = &quot;Simulated VAF&quot;, y = &quot;Score&quot;, fill = NULL, color = NULL) + theme_classic(base_size = 14) + theme(axis.text.x = element_text(size = 11, color = &quot;black&quot;), axis.text.y = element_text(size = 11, color = &quot;black&quot;), axis.title = element_text(size = 15, color = &quot;black&quot;, face = &quot;bold&quot;), strip.text = element_text(size = 14, face = &quot;bold&quot;), legend.position = &quot;top&quot;, legend.text = element_text(size = 11), panel.grid.major.y = element_line(color = &quot;grey90&quot;, linewidth = 0.3)) ggsave(file.path(out_dir, &quot;VAF_Recall_Precision_F1_boxplot.pdf&quot;), p_all, width = 12, height = 4.5) ggsave(file.path(out_dir, &quot;VAF_Recall_Precision_F1_boxplot.png&quot;), p_all, width = 12, height = 4.5, dpi = 300) message(&quot;[DONE] output: &quot;, out_dir) Figure 4.1: Precision, recall, and F1-score of five variant callers evaluated using spike-in simulations across different simulated VAFs. For each sample, approximately 10,000 synthetic SNVs were introduced into regions with sequencing depth ≥40X for each condition. 4.2 Smart-seq2 DP simulation simulation-region preparation BASE=&quot;/mnt/storage/tantingting/scmut_smart&quot; MANIFEST=&quot;${BASE}/bam/star_qc_unique_ge10k_scrna_sample_wes.tsv&quot; # Protein-coding exon regions EXON_BED=&quot;/mnt/storage/tantingting/scmut/simu/region/protein_coding_exon.merged.bed&quot; # Precomputed scRNA-seq regions with DP &gt;= 1 SCRNA_GE1_BASE=&quot;${BASE}/WES_gold/smartseq_callable&quot; # Precomputed union sites from seven callers with ±100 bp flanking regions UNION_DIR=&quot;${BASE}/simu/union_sites&quot; OUT_DIR=&quot;${BASE}/simu/region/dp_sim_region&quot; mkdir -p &quot;$OUT_DIR&quot; echo -e &quot;Sample	SRR	WES_SRR	Dataset	N_region	Length_bp	Length_Mb&quot; \ &gt; &quot;${OUT_DIR}/final_region_summary.tsv&quot; tail -n +2 &quot;$MANIFEST&quot; | while read -r scRNA_SRR sample WES_SRR do [[ -n &quot;$scRNA_SRR&quot; &amp;&amp; -n &quot;$sample&quot; ]] || continue # Determine the dataset based on the sample ID if [[ &quot;$sample&quot; == PT* ]]; then DATASET=&quot;1_TNBC&quot; SCRNA_GE1_DIR=&quot;${SCRNA_GE1_BASE}/TNBC/scrna_ge1&quot; elif [[ &quot;$sample&quot; == BC* ]]; then DATASET=&quot;2_BRCA&quot; SCRNA_GE1_DIR=&quot;${SCRNA_GE1_BASE}/BRCA/scrna_ge1&quot; else echo &quot;[WARN] skip $sample $scRNA_SRR&quot; continue fi echo &quot;==============================&quot; echo &quot;[INFO] Sample : $sample&quot; echo &quot;[INFO] SRR : $scRNA_SRR&quot; echo &quot;[INFO] Dataset: $DATASET&quot; # Input files scrna_bed=&quot;${SCRNA_GE1_DIR}/${scRNA_SRR}_scRNA_ge1.bed&quot; union_bed=&quot;${UNION_DIR}/${scRNA_SRR}.union_7tools.plusminus100bp.bed&quot; final_bed=&quot;${OUT_DIR}/${scRNA_SRR}.final_sim_region_ge1.bed&quot; if [[ ! -s &quot;$scrna_bed&quot; ]]; then echo &quot;[WARN] missing scRNA ge1: $scrna_bed&quot; continue fi if [[ ! -s &quot;$union_bed&quot; ]]; then echo &quot;[WARN] missing union: $union_bed&quot; continue fi # Intersect exon regions with scRNA-seq DP &gt;= 1 regions intersect_bed=&quot;${OUT_DIR}/${scRNA_SRR}.exon_ge1.tmp.bed&quot; bedtools intersect \ -a &quot;$EXON_BED&quot; \ -b &quot;$scrna_bed&quot; \ -wa -u | bedtools sort -i - | bedtools merge -i - &gt; &quot;$intersect_bed&quot; # Exclude union sites and their ±100 bp flanking regions bedtools subtract \ -a &quot;$intersect_bed&quot; \ -b &quot;$union_bed&quot; | bedtools sort -i - | bedtools merge -i - &gt; &quot;$final_bed&quot; rm -f &quot;$intersect_bed&quot; # Summarize the final simulation regions n_region=$(wc -l &lt; &quot;$final_bed&quot;) length_bp=$(awk &#39;{sum += $3-$2} END{print sum+0}&#39; &quot;$final_bed&quot;) length_mb=$(awk &#39;{sum += $3-$2} END{printf &quot;%.4f&quot;,sum/1000000}&#39; &quot;$final_bed&quot;) echo -e \ &quot;${sample}	${scRNA_SRR}	${WES_SRR}	${DATASET}	${n_region}	${length_bp}	${length_mb}&quot; \ &gt;&gt; &quot;${OUT_DIR}/final_region_summary.tsv&quot; echo &quot;[INFO] Final regions: $n_region&quot; echo &quot;[INFO] Length : ${length_mb} Mb&quot; done echo &quot;==============================&quot; echo &quot;[INFO] Finished&quot; column -t -s $&#39;	&#39; &quot;${OUT_DIR}/final_region_summary.tsv&quot; DP simulation code #!/bin/bash # Smart-seq2 DP effective-bin simulation # # 1. Randomly generate 50,000 candidate sites from Smart-seq2 callable regions with DP &gt;= 1 # 2. Scan the BAM to calculate effective DP: Q&gt;=20, A/C/G/T base, remove duplicate/secondary/supplementary/qcfail # 3. Assign sites to mutually exclusive effective-DP bins: DP5-10, DP10-25, DP25-50,DP&gt;=50 # 4. Simulate up to 3,000 sites per bin # 5. Perform direct spike-in at a fixed VAF of 0.4 REF=/home/tantingting/scmut/ref/bwa_ref/genome.fa OUTDIR=/mnt/storage/tantingting/scmut_smart/simu/direct_spike_dp_effbin_q20_vaf04_final MANIFEST=/mnt/storage/tantingting/scmut_smart/bam/star_qc_unique_ge10k_scrna_sample_wes.tsv REGION_DIR=/mnt/storage/tantingting/scmut_smart/simu/region/dp_sim_region N_CANDIDATE=50000 FLANK=0 FIXED_VAF=0.4 N_SITE=3000 MINMUTREADS=2 THREADS=16 SEED=1234 MIN_BQ=20 MIN_MQ=0 DP_BINS=(&quot;5_10&quot; &quot;10_25&quot; &quot;25_50&quot; &quot;50plus&quot;) mkdir -p ${OUTDIR}/{scripts,sites,window,bam,cache,truth,log,summary} samples=(&quot;$@&quot;) if [[ ${#samples[@]} -eq 0 ]]; then echo &quot;[ERROR] No sample specified&quot; exit 1 fi get_bam(){ srr=$1 sample=$(awk -v s=&quot;$srr&quot; &#39;$1==s{print $2}&#39; ${MANIFEST}) if [[ $sample == PT* ]]; then echo &quot;/mnt/storage/tantingting/scmut_smart/bam/1_TNBC_scRNA/md_bam/${srr}_sortmd.bam&quot; elif [[ $sample == BC* ]]; then echo &quot;/mnt/storage/tantingting/scmut_smart/bam/2_BRCA_scRNA/md_bam/${srr}_sortmd.bam&quot; else echo &quot;NA&quot; fi } ########################################################### # Step 1:Randomly generate candidate variant sites from Smart-seq2 callable regions # # Input: final_sim_region_ge1.bed # # Procedure: # 1. Randomly select genomic positions within callable regions # 2. Retrieve the reference allele from the reference genome # 3. Randomly generate an alternative allele # # Output: candidate_sites.txt # # Note: # Candidate sites are not the final simulated variants; they are subsequently filtered based on the actual effective DP. ########################################################### cat &gt; ${OUTDIR}/scripts/make_candidate_sites.py &lt;&lt; &#39;PY&#39; import sys, random, subprocess, bisect region_bed, ref, n_site, out, seed = ( sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4], int(sys.argv[5]) ) random.seed(seed) bases=[&quot;A&quot;,&quot;C&quot;,&quot;G&quot;,&quot;T&quot;] regions=[] cum=[] total=0 with open(region_bed) as f: for line in f: if not line.strip() or line.startswith(&quot;#&quot;): continue chrom,start,end=line.strip().split()[:3] start=int(start) end=int(end) if end&lt;=start: continue total += end-start regions.append((chrom,start,end)) cum.append(total) seen=set() with open(out,&quot;w&quot;) as w: tries=0 max_tries=n_site*300 while len(seen)&lt;n_site and tries&lt;max_tries: tries+=1 idx=bisect.bisect_left( cum, random.randint(1,total) ) chrom,start,end=regions[idx] pos=random.randint(start,end-1)+1 if (chrom,pos) in seen: continue try: fa=subprocess.check_output( [ &quot;samtools&quot;, &quot;faidx&quot;, ref, f&quot;{chrom}:{pos}-{pos}&quot; ], text=True ).splitlines() ref_base=&quot;&quot;.join(fa[1:]).upper() except: continue if ref_base not in bases: continue alt=random.choice( [x for x in bases if x!=ref_base] ) seen.add((chrom,pos)) w.write( f&quot;{chrom}	{pos}	{pos}	{ref_base}	{alt}
&quot; ) print( f&quot;[INFO] candidate sites generated: {len(seen)}&quot;, file=sys.stderr ) PY ########################################################### # Step 2: Calculate the actual effective sequencing depth at candidate sites # # Purpose: Determine the number of reads eligible for simulation at each site using the original Smart-seq2 BAM. # # A read contributes to effective DP only if: # 1. The read is mapped # 2. It is not a secondary alignment # 3. It is not a supplementary alignment # 4. It is not marked as a duplicate # 5. It has not failed QC # 6. Mapping quality &gt;= MIN_MQ # 7. Base quality &gt;= MIN_BQ # 8. The aligned base is A/C/G/T # # The output cache contains: # ref # alt # effective_dp: Number of A/C/G/T bases aligned to this site with BQ &gt;= MIN_BQ # ref_count: Number of bases matching the reference allele among effective-DP observations # candidate_fragments: Set of query names eligible for conversion to alt; only reads/fragments with base == ref and BQ &gt;= MIN_BQ are recorded ########################################################### cat &gt; ${OUTDIR}/scripts/build_effective_cache.py &lt;&lt; &#39;PY&#39; import sys import pysam import pickle from collections import defaultdict bam_file=sys.argv[1] candidate_file=sys.argv[2] out_cache=sys.argv[3] MIN_BQ=int(sys.argv[4]) MIN_MQ=int(sys.argv[5]) sites={} chr_sites=defaultdict(set) with open(candidate_file) as f: for line in f: chrom,pos,end,ref,alt=line.strip().split() pos=int(pos) sites[(chrom,pos)]={ &quot;ref&quot;:ref, &quot;alt&quot;:alt, &quot;effective_dp&quot;:0, &quot;ref_count&quot;:0, &quot;candidate_fragments&quot;:set() } chr_sites[chrom].add(pos) bam=pysam.AlignmentFile( bam_file, &quot;rb&quot; ) for chrom in chr_sites: positions=sorted(chr_sites[chrom]) pos_set=set(positions) print( f&quot;[INFO] scanning {chrom}&quot;, file=sys.stderr ) try: reads=bam.fetch( chrom, min(positions)-1, max(positions) ) except: continue for r in reads: if ( r.is_unmapped or r.is_secondary or r.is_supplementary or r.is_duplicate or r.is_qcfail ): continue if r.mapping_quality &lt; MIN_MQ: continue if ( r.query_sequence is None or r.query_qualities is None ): continue seq=r.query_sequence qual=r.query_qualities for qp,rp in r.get_aligned_pairs( matches_only=False ): if qp is None or rp is None: continue pos=rp+1 if pos not in pos_set: continue if qual[qp] &lt; MIN_BQ: continue base=seq[qp].upper() if base not in &quot;ACGT&quot;: continue info=sites[(chrom,pos)] info[&quot;effective_dp&quot;] += 1 if base == info[&quot;ref&quot;]: info[&quot;ref_count&quot;] += 1 info[&quot;candidate_fragments&quot;].add( r.query_name ) bam.close() with open(out_cache,&quot;wb&quot;) as f: pickle.dump( sites, f, protocol=pickle.HIGHEST_PROTOCOL ) print( f&quot;[INFO] saved {out_cache}&quot;, file=sys.stderr ) for label,func in [ (&quot;DP1plus&quot;, lambda x:x[&quot;effective_dp&quot;]&gt;=1), (&quot;DP5plus&quot;, lambda x:x[&quot;effective_dp&quot;]&gt;=5), (&quot;DP10plus&quot;, lambda x:x[&quot;effective_dp&quot;]&gt;=10), (&quot;DP25plus&quot;, lambda x:x[&quot;effective_dp&quot;]&gt;=25), (&quot;DP50plus&quot;, lambda x:x[&quot;effective_dp&quot;]&gt;=50), ]: print( label, sum( func(x) for x in sites.values() ), file=sys.stderr ) PY ########################################################### # Python 2: select_sites_by_effbin.py # # Function: # Select sites from the effective cache by mutually exclusive DP bins # # Criteria: # 1. effective_dp falls within the corresponding interval # 2. candidate_fragments &gt;= ceil(effective_dp * VAF) # # The second criterion is important: # Insufficient reference-supporting reads prevent the target VAF of 0.4 from being achieved ########################################################### cat &gt; ${OUTDIR}/scripts/select_sites_by_effbin.py &lt;&lt; &#39;PY&#39; import sys, pickle, random, math cache_file, dp_bin, n_site, vaf, min_mutreads, out, seed = sys.argv[1:8] n_site = int(n_site) vaf = float(vaf) min_mutreads = int(min_mutreads) seed = int(seed) random.seed(seed) if dp_bin == &quot;5_10&quot;: lo, hi = 5,10 elif dp_bin == &quot;10_25&quot;: lo, hi = 10,25 elif dp_bin == &quot;25_50&quot;: lo, hi = 25,50 elif dp_bin == &quot;50plus&quot;: lo, hi = 50,None else: sys.exit(f&quot;Unknown dp_bin: {dp_bin}&quot;) with open(cache_file, &quot;rb&quot;) as f: cache = pickle.load(f) eligible = [] for (chrom, pos), info in cache.items(): dp = info[&quot;effective_dp&quot;] ref_count = info[&quot;ref_count&quot;] n_candidate = len(info[&quot;candidate_fragments&quot;]) need_alt = max(min_mutreads, math.ceil(dp * vaf)) in_bin = dp &gt;= lo if hi is None else lo &lt;= dp &lt; hi if in_bin and n_candidate &gt;= need_alt: eligible.append((chrom, pos, info[&quot;ref&quot;], info[&quot;alt&quot;], dp, ref_count, n_candidate, need_alt)) eligible.sort(key=lambda x: (x[0], x[1])) print(f&quot;[INFO] {dp_bin} eligible={len(eligible)}&quot;, file=sys.stderr) if len(eligible) == 0: sys.exit(f&quot;No eligible sites for {dp_bin}&quot;) if len(eligible) &gt; n_site: selected = random.sample(eligible, n_site) selected.sort(key=lambda x: (x[0], x[1])) else: selected = eligible print(f&quot;[WARN] eligible &lt; N_SITE, use all: {len(selected)}&quot;, file=sys.stderr) with open(out, &quot;w&quot;) as w: for chrom, pos, ref, alt, dp, ref_count, n_candidate, need_alt in selected: # chrom pos end vaf ref alt effective_dp_q20 ref_count_q20 candidate_fragments_q20 need_alt dp_bin w.write(f&quot;{chrom}	{pos}	{pos}	{vaf}	{ref}	{alt}	{dp}	{ref_count}	{n_candidate}	{need_alt}	{dp_bin}
&quot;) print(f&quot;[INFO] selected={len(selected)}&quot;, file=sys.stderr) PY ########################################################### # Python 3: direct_spike_from_effective_cache.py # # Function: # Perform direct spike-in on the BAM using selected sites and the effective cache # # Logic: # 1. Modify need_alt candidate fragments at each site # 2. Candidate fragments have already been restricted during build_effective_cache to: # base == ref and BQ &gt;= MIN_BQ # 3. The second pass that edits the BAM also requires BQ &gt;= MIN_BQ # This keeps effective_dp_q20 and mut_bases_edited in the truth file consistent # # Truth output: # effective_dp_q20 # ref_count_q20 # candidate_fragments_q20 # mut_fragments_planned # mut_bases_edited # real_vaf = mut_bases_edited / effective_dp_q20 ########################################################### cat &gt; ${OUTDIR}/scripts/direct_spike_from_effective_cache.py &lt;&lt; &#39;PY&#39; import sys, random, pysam, pickle from collections import defaultdict bam_in, sites_file, bam_out, truth_out, seed, cache_file, min_bq = sys.argv[1:8] seed = int(seed) min_bq = int(min_bq) random.seed(seed) with open(cache_file, &quot;rb&quot;) as f: cache = pickle.load(f) sites = [] with open(sites_file) as f: for line in f: if not line.strip() or line.startswith(&quot;#&quot;): continue fs = line.strip().split() chrom = fs[0] pos = int(fs[1]) vaf = float(fs[3]) ref = fs[4].upper() alt = fs[5].upper() dp = int(fs[6]) ref_count = int(fs[7]) n_candidate = int(fs[8]) need_alt = int(fs[9]) dp_bin = fs[10] sites.append((chrom, pos, vaf, ref, alt, dp, ref_count, n_candidate, need_alt, dp_bin)) fragment_edit_map = {} truth = [] for chrom, pos, vaf, ref, alt, dp, ref_count, n_candidate, need_alt, dp_bin in sites: info = cache.get((chrom, pos)) if info is None: continue candidates = list(info[&quot;candidate_fragments&quot;]) if len(candidates) &lt; need_alt: continue chosen = random.sample(candidates, need_alt) for qname in chosen: fragment_edit_map[(chrom, pos, qname)] = alt truth.append((chrom, pos, ref, alt, dp, ref_count, len(candidates), need_alt, dp_bin)) edit_by_qname = defaultdict(lambda: defaultdict(dict)) for chrom, pos, qname in fragment_edit_map: edit_by_qname[qname][chrom][pos] = fragment_edit_map[(chrom, pos, qname)] bam = pysam.AlignmentFile(bam_in, &quot;rb&quot;) out = pysam.AlignmentFile(bam_out, &quot;wb&quot;, template=bam) site_edited_bases = defaultdict(int) edited_reads = 0 edited_bases = 0 for r in bam: if r.is_unmapped or r.is_secondary or r.is_supplementary or r.is_duplicate or r.is_qcfail or r.query_sequence is None: out.write(r) continue qname = r.query_name if qname not in edit_by_qname: out.write(r) continue chrom = r.reference_name if chrom is None or chrom not in edit_by_qname[qname]: out.write(r) continue if r.query_qualities is None: out.write(r) continue target = edit_by_qname[qname][chrom] seq = list(r.query_sequence) quals = r.query_qualities changed = 0 for qp, rp in r.get_aligned_pairs(matches_only=False): if qp is None or rp is None: continue pos = rp + 1 if pos not in target: continue # Keep consistent with the effective cache: only bases with BQ &gt;= MIN_BQ may be edited if quals[qp] &lt; min_bq: continue alt = target[pos] if qp &lt; len(seq) and seq[qp].upper() in &quot;ACGT&quot; and seq[qp].upper() != alt: seq[qp] = alt changed += 1 site_edited_bases[(chrom, pos)] += 1 if changed &gt; 0: r.query_sequence = &quot;&quot;.join(seq) r.query_qualities = quals edited_reads += 1 edited_bases += changed out.write(r) out.close() bam.close() with open(truth_out, &quot;w&quot;) as w: w.write(&quot;chrom	pos	ref	alt	effective_dp_q20	ref_count_q20	candidate_fragments_q20	mut_fragments_planned	mut_bases_edited	real_vaf	dp_bin
&quot;) for chrom, pos, ref, alt, dp, ref_count, n_candidate, need_alt, dp_bin in truth: mut_bases = site_edited_bases.get((chrom, pos), 0) real_vaf = mut_bases / dp if dp &gt; 0 else 0 w.write(&quot;	&quot;.join(map(str, [ chrom, pos, ref, alt, dp, ref_count, n_candidate, need_alt, mut_bases, real_vaf, dp_bin ])) + &quot;
&quot;) print(f&quot;[INFO] truth_sites={len(truth)}&quot;, file=sys.stderr) print(f&quot;[INFO] edited_reads={edited_reads}&quot;, file=sys.stderr) print(f&quot;[INFO] edited_bases={edited_bases}&quot;, file=sys.stderr) PY ########################################################### # Manifest ########################################################### manifest=${OUTDIR}/summary/prepare_manifest.tsv if [[ ! -s ${manifest} ]]; then echo -e \ &quot;Sample	Mode	VAF	DP_bin	CandidateSites	SubsetBam	EffectiveCache	SelectedSites	SpikeinBam	CalmdBam	Truth&quot; \ &gt; ${manifest} fi ########################################################### # Main loop ########################################################### for sample in &quot;${samples[@]}&quot;; do echo &quot;========== ${sample} ==========&quot; bam=$(get_bam ${sample}) region_bed=${REGION_DIR}/${sample}.final_sim_region_ge1.bed candidate_sites=${OUTDIR}/sites/${sample}.candidate_sites.txt sample_subset=${OUTDIR}/bam/${sample}.candidate.original_subset.bam eff_cache=${OUTDIR}/cache/${sample}.site_info.effective_q${MIN_BQ}.pkl candidate_window=${OUTDIR}/window/${sample}.candidate.window.bed [[ -s ${bam} ]] || { echo &quot;[SKIP] BAM missing: ${bam}&quot; continue } [[ -s ${region_bed} ]] || { echo &quot;[SKIP] region missing: ${region_bed}&quot; continue } ####################################################### # Step 0 # final region -&gt; 50000 candidate sites ####################################################### if [[ -s ${candidate_sites} ]]; then echo &quot;[0] candidate exists&quot; else echo &quot;[0] generate candidate sites&quot; python ${OUTDIR}/scripts/make_candidate_sites.py \ ${region_bed} \ ${REF} \ ${N_CANDIDATE} \ ${candidate_sites} \ ${SEED} fi ####################################################### # Step 0.5 # subset BAM ####################################################### if [[ -s ${candidate_window} ]]; then echo &quot;[2] candidate window exists, skip: ${candidate_window}&quot; else echo &quot;[2] make candidate window&quot; awk -v OFS=&quot;	&quot; -v flank=${FLANK} &#39;{s=$2-1-flank; e=$3+flank; if(s&lt;0)s=0; print $1,s,e}&#39; ${candidate_sites} \ | sort -k1,1 -k2,2n \ | bedtools merge \ &gt; ${candidate_window} fi if [[ -s ${sample_subset} &amp;&amp; -s ${sample_subset}.bai ]]; then echo &quot;[3] candidate subset BAM exists, skip: ${sample_subset}&quot; else echo &quot;[3] subset BAM once&quot; samtools view -@ ${THREADS} -P -b -L ${candidate_window} ${bam} &gt; ${sample_subset} samtools index ${sample_subset} fi ####################################################### # Step 1 ####################################################### if [[ -s ${eff_cache} ]]; then echo &quot;[1] effective cache exists, skip: ${eff_cache}&quot; else echo &quot;[1] build effective cache from 50000 sites&quot; python ${OUTDIR}/scripts/build_effective_cache.py \ ${sample_subset} \ ${candidate_sites} \ ${eff_cache} \ ${MIN_BQ} \ ${MIN_MQ} \ &gt; ${OUTDIR}/log/${sample}.build_effective_cache.log 2&gt;&amp;1 fi ####################################################### # Step 2-5 # For each mutually exclusive DP bin: # Select sites -&gt; spike-in -&gt; sort/index -&gt; calmd/index ####################################################### for bin in &quot;${DP_BINS[@]}&quot;; do tag=${sample}.vaf${FIXED_VAF}.dpbin${bin}.q${MIN_BQ} selected_sites=${OUTDIR}/sites/${tag}.selected_sites.txt spikein=${OUTDIR}/bam/${tag}.spikein.bam spikein_sorted=${OUTDIR}/bam/${tag}.spikein.sorted.bam spikein_calmd=${OUTDIR}/bam/${tag}.spikein.sorted.calmd.bam truth=${OUTDIR}/truth/${tag}.truth.tsv echo &quot;[2] ${sample} DPbin=${bin}&quot; if [[ -s ${selected_sites} ]]; then echo &quot;[2] selected sites exists, skip: ${selected_sites}&quot; else echo &quot;[2] select sites by effective DP bin&quot; python ${OUTDIR}/scripts/select_sites_by_effbin.py \ ${eff_cache} \ ${bin} \ ${N_SITE} \ ${FIXED_VAF} \ ${MINMUTREADS} \ ${selected_sites} \ $((SEED + ${#bin})) \ &gt; ${OUTDIR}/log/${tag}.select_sites.log 2&gt;&amp;1 fi n_selected=$(wc -l &lt; ${selected_sites}) echo &quot;[INFO] selected sites: ${n_selected}&quot; [[ ${n_selected} -gt 0 ]] || { echo &quot;[SKIP] no selected sites: ${tag}&quot;; continue; } if [[ -s ${spikein_calmd} &amp;&amp; -s ${spikein_calmd}.bai &amp;&amp; -s ${truth} ]]; then echo &quot;[3] calmd spike-in BAM exists, skip: ${spikein_calmd}&quot; else echo &quot;[3] direct spike-in&quot; python ${OUTDIR}/scripts/direct_spike_from_effective_cache.py \ ${sample_subset} \ ${selected_sites} \ ${spikein} \ ${truth} \ $((SEED + ${#bin})) \ ${eff_cache} \ ${MIN_BQ} \ &gt; ${OUTDIR}/log/${tag}.spikein.log 2&gt;&amp;1 [[ -s ${spikein} ]] || { echo &quot;[ERROR] spike-in failed: ${tag}&quot;; continue; } echo &quot;[4] sort/index&quot; samtools sort -@ ${THREADS} -o ${spikein_sorted} ${spikein} samtools index ${spikein_sorted} samtools quickcheck ${spikein_sorted} echo &quot;[5] calmd/index&quot; samtools calmd -@ ${THREADS} -b ${spikein_sorted} ${REF} &gt; ${spikein_calmd} samtools index ${spikein_calmd} samtools quickcheck ${spikein_calmd} fi n_truth=$(($(wc -l &lt; ${truth}) - 1)) echo &quot;[INFO] truth sites: ${n_truth}&quot; if ! awk \ -v s=&quot;${sample}&quot; \ -v v=&quot;${FIXED_VAF}&quot; \ -v b=&quot;${bin}&quot; \ &#39;$1==s &amp;&amp; $2==&quot;DPBIN_Q20&quot; &amp;&amp; $3==v &amp;&amp; $4==b{found=1} END{exit found?0:1}&#39; \ ${manifest} then echo -e &quot;${sample}	DPBIN_Q20	${FIXED_VAF}	${bin}	${candidate_sites}	${subset_bam}	${eff_cache}	${selected_sites}	${spikein_sorted}	${spikein_calmd}	${truth}&quot; \ &gt;&gt; ${manifest} fi done echo &quot;[DONE] ${sample}&quot; done DP simulation plotting suppressPackageStartupMessages({ library(data.table) library(dplyr) library(ggplot2) library(stringr) }) # Path configuration base_dir &lt;- &quot;/mnt/storage/tantingting/scmut_smart/simu/direct_spike_dp_effbin_q20_vaf04_final&quot; truth_dir &lt;- file.path(base_dir, &quot;truth&quot;) vcf_dir &lt;- file.path(base_dir, &quot;caller/newonly&quot;) out_dir &lt;- file.path(base_dir, &quot;performance_plot&quot;) dir.create(out_dir, recursive = TRUE, showWarnings = FALSE) # Variant callers, fixed VAF, and DP bins tools &lt;- c(&quot;Freebayes&quot;, &quot;Strelka2&quot;, &quot;scallele&quot;, &quot;Samtools&quot;, &quot;Monovar&quot;, &quot;VarScan2&quot;) vaf &lt;- &quot;0.4&quot; dp_bins &lt;- c(&quot;dpbin5_10&quot;, &quot;dpbin10_25&quot;, &quot;dpbin25_50&quot;, &quot;dpbin50plus&quot;) dp_labels &lt;- c(&quot;5-10&quot;, &quot;10-25&quot;, &quot;25-50&quot;, &quot;≥50&quot;) # Automatically identify samples and DP bins from truth files truth_files &lt;- list.files(truth_dir, pattern = &quot;\.truth\.tsv$&quot;, full.names = FALSE) truth_files &lt;- truth_files[grepl(paste0(&quot;\.vaf&quot;, vaf, &quot;\.&quot;), truth_files)] info &lt;- data.table(file = truth_files) info[, sample := sub(paste0(&quot;\.vaf&quot;, vaf, &quot;\..*$&quot;), &quot;&quot;, file)] info[, dp_bin := str_extract(file, &quot;dpbin[^.]+&quot;)] cat(&quot;========================================
