&quot;) # Read truth variants read_truth &lt;- function(f){ x &lt;- fread(f) names(x) &lt;- str_replace_all(names(x), &quot;^#&quot;, &quot;&quot;) x[, chrom := as.character(chrom)] x[, pos := as.integer(pos)] x[, ref := toupper(ref)] x[, alt := toupper(alt)] unique(x[, .(chrom, pos, ref, alt)]) } # Read VCF variants read_vcf &lt;- function(f){ empty &lt;- data.table(chrom = character(), pos = integer(), ref = character(), alt = character()) if(!file.exists(f)){ warning(&quot;VCF does not exist: &quot;, f) return(empty) } x &lt;- tryCatch( fread(cmd = sprintf( &quot;bcftools query -f &#39;%%CHROM\t%%POS\t%%REF\t%%ALT\n&#39; %s&quot;, shQuote(f) ), header = FALSE), error = function(e){ warning(&quot;Failed to read VCF: &quot;, f) empty } ) if(nrow(x) == 0) return(empty) setnames(x, c(&quot;chrom&quot;, &quot;pos&quot;, &quot;ref&quot;, &quot;alt&quot;)) x[, chrom := as.character(chrom)] x[, pos := as.integer(pos)] x[, ref := toupper(ref)] x[, alt := toupper(alt)] # Split multiallelic ALT records x &lt;- x[, .(alt = unlist(strsplit(alt, &quot;,&quot;))), by = .(chrom, pos, ref)] # Retain SNVs only x &lt;- x[nchar(ref) == 1 &amp; nchar(alt) == 1] unique(x) } # Calculate variant calling performance res &lt;- list() k &lt;- 1 for(i in seq_len(nrow(info))){ sample &lt;- info$sample[i] dp_bin &lt;- info$dp_bin[i] cat(sprintf(&quot;[%d/%d] sample=%s dp=%s
&quot;, i, nrow(info), sample, dp_bin)) flush.console() truth_file &lt;- file.path(truth_dir, info$file[i]) truth &lt;- read_truth(truth_file) truth_key &lt;- paste(truth$chrom, truth$pos, truth$ref, truth$alt, sep = &quot;:&quot;) for(tool in tools){ vcf_file &lt;- file.path( vcf_dir, paste0(sample, &quot;.vaf&quot;, vaf, &quot;.&quot;, dp_bin, &quot;.q20.&quot;, tool, &quot;.newonly.vcf.gz&quot;) ) call &lt;- read_vcf(vcf_file) call_key &lt;- paste(call$chrom, call$pos, call$ref, call$alt, sep = &quot;:&quot;) tp &lt;- sum(call_key %in% truth_key) fp &lt;- sum(!call_key %in% truth_key) fn &lt;- sum(!truth_key %in% call_key) precision &lt;- ifelse(tp + fp &gt; 0, tp / (tp + fp), NA) recall &lt;- ifelse(tp + fn &gt; 0, tp / (tp + fn), NA) f1 &lt;- ifelse( is.na(precision) | is.na(recall) | precision + recall == 0, NA, 2 * precision * recall / (precision + recall) ) res[[k]] &lt;- data.table( sample = sample, dp_bin = dp_bin, tool = tool, truth_n = length(truth_key), call_n = length(call_key), TP = tp, FP = fp, FN = fn, Precision = precision, Recall = recall, F1 = f1 ) k &lt;- k + 1 } # Save a checkpoint every 50 truth files if(i %% 50 == 0){ tmp &lt;- rbindlist(res, fill = TRUE) fwrite(tmp, file.path(out_dir, &quot;dp_performance_summary.tmp.tsv&quot;), sep = &quot;	&quot;) cat(&quot;Checkpoint saved:&quot;, i, &quot;/&quot;, nrow(info), &quot;
